package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7a;
import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.*;
class TaskScaleupFixtureIntegrityTest { @Test void controlledFixturesHaveSixteenValidExactDateRows() throws Exception { for(String p:List.of("order-summary-stage7a.json","negative-comments-stage7a.json","product-candidates-stage7a.json","ad-performance-stage7a.json","external-reports-stage7a.json")){ List<Map<String,Object>> rows=Stage7ATaskDatasetSupport.listResource("/benchmark/v1/task/fixtures/stage7a/"+p); assertThat(rows).hasSize(16); assertThat(rows).allSatisfy(r->{assertThat(((Number)r.get("tenantId")).intValue()).isPositive(); assertThat(((Number)r.get("shopId")).intValue()).isPositive(); assertThat(r.get("startDate")).isEqualTo(r.get("endDate"));}); } }}
